int largestRectangleArea(int *heights, int heightsSize) {
  int *stack = (int *)malloc(sizeof(int) * (heightsSize + 1));
  int top = -1, maxArea = 0;
  for (int i = 0; i <= heightsSize; i++) {
    int h = (i == heightsSize) ? 0 : heights[i];
    while (top >= 0 && heights[stack[top]] > h) {
      int height = heights[stack[top--]];
      int width = top < 0 ? i : i - stack[top] - 1;
      if (height * width > maxArea) maxArea = height * width;
    }
    stack[++top] = i;
  }
  free(stack);
  return maxArea;
}

class Solution {
public:
  int largestRectangleArea(vector<int> &heights) {
    int n = heights.size(), maxArea = 0;
    stack<int> st;
    for (int i = 0; i <= n; i++) {
      int h = (i == n) ? 0 : heights[i];
      while (!st.empty() && heights[st.top()] > h) {
        int height = heights[st.top()];
        st.pop();
        int width = st.empty() ? i : i - st.top() - 1;
        maxArea = max(maxArea, height * width);
      }
      st.push(i);
    }
    return maxArea;
  }
};

func largestRectangleArea(heights []int) int {
	stack := []int{}
	maxArea := 0
	n := len(heights)
	for i := 0; i <= n; i++ {
		h := 0
		if i < n {
			h = heights[i]
		}
		for len(stack) > 0 && heights[stack[len(stack)-1]] > h {
			height := heights[stack[len(stack)-1]]
			stack = stack[:len(stack)-1]
			width := i
			if len(stack) > 0 {
				width = i - stack[len(stack)-1] - 1
			}
			if height*width > maxArea {
				maxArea = height * width
			}
		}
		stack = append(stack, i)
	}
	return maxArea
}

class Solution {
  public int largestRectangleArea(int[] heights) {
    int n = heights.length, maxArea = 0;
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
      int h = (i == n) ? 0 : heights[i];
      while (!st.isEmpty() && heights[st.peek()] > h) {
        int height = heights[st.pop()];
        int width = st.isEmpty() ? i : i - st.peek() - 1;
        maxArea = Math.max(maxArea, height * width);
      }
      st.push(i);
    }
    return maxArea;
  }
}

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        n = len(heights)
        st = []
        max_area = 0
        for i in range(n + 1):
            h = heights[i] if i < n else 0
            while st and heights[st[-1]] > h:
                height = heights[st.pop()]
                width = i if not st else i - st[-1] - 1
                max_area = max(max_area, height * width)
            st.append(i)
        return max_area

impl Solution {
  pub fn largest_rectangle_area(heights: Vec<i32>) -> i32 {
    let n = heights.len();
    let mut st: Vec<usize> = vec![];
    let mut max_area = 0;
    for i in 0..=n {
      let h = if i < n { heights[i] } else { 0 };
      while let Some(&top) = st.last() {
        if heights[top] <= h {
          break;
        }
        let height = heights[st.pop().unwrap()];
        let width = if st.is_empty() {
          i as i32
        } else {
          i as i32 - *st.last().unwrap() as i32 - 1
        };
        max_area = max_area.max(height * width);
      }
      st.push(i);
    }
    max_area
  }
}

const largestRectangleArea = (heights: number[]): number => {
  const n = heights.length;
  const st: number[] = [];
  let maxArea = 0;
  for (let i = 0; i <= n; i++) {
    const h = i < n ? heights[i] : 0;
    while (st.length && heights[st[st.length - 1]] > h) {
      const height = heights[st.pop()!];
      const width = st.length === 0 ? i : i - st[st.length - 1] - 1;
      maxArea = Math.max(maxArea, height * width);
    }
    st.push(i);
  }
  return maxArea;
};
